"""丹青需求单和库卡检查（只用标准库）。
用法：
  python3 check_brief.py <需求单.json> [--lib 库目录]   查一张需求单
  python3 check_brief.py --library [库目录]             查库里的场景、品牌元素、参考卡
  python3 check_brief.py --card <卡.md>                 只查一张卡（主人收进我的库的参考卡等）
库目录默认先找 ~/.yunjian/paint/库，没有再找本文件往上两级的 库/（开发仓库里）。
有问题打印 ❌ 并以 1 退出；全过打印 ✅。"""
import json
import re
import sys
from pathlib import Path

MENU = ["1:1 主图", "3:4 主图", "白底图", "详情图", "模特上身图", "场景图", "细节图",
        "封面", "文章配图", "信息图", "小红书图文卡片", "海报", "直播封面", "直播头图", "菜单外"]
ZHUTI = ["商品为主", "人物为主", "人＋货", "场景为主", "内容为主"]
BRAND = ["加（主人给）", "加（丹青出方案）", "不加", "待问"]
SOURCE = ["主人", "推荐"]
KEYS = ["版本", "日期", "一句话", "主体", "平台", "用途", "要什么", "套餐", "规格", "景", "品牌元素", "参考", "提醒", "主人确认"]
KEYS_SINGLE = ["版本", "日期", "一句话", "档", "平台", "要什么", "规格", "想法", "提示词", "提醒"]  # 单图：不走七问（判档卡）
DANG = ["单图", "系列图"]

CARD_KINDS = {  # 库子目录 -> (卡头「类」, 卡头必填字段, 正文必有的小节)
    "场景": ("场景", ["景", "名字", "适用图", "适用主体"], ["什么样", "提示词片段（中）", "提示词片段（英）", "注意"]),
    "品牌元素": ("品牌元素", ["元素", "名字", "适用图"], ["什么样", "怎么做", "平台提醒（只提醒，主人定）", "注意"]),
    "参考": ("参考", ["图类", "名字", "适用平台"], ["什么样", "为什么好用", "怎么出", "注意"]),
}
COMMON = ["id", "类", "版本", "用过", "选中"]


def find_lib(arg=None):
    for p in ([Path(arg).expanduser()] if arg else []) + [Path.home() / ".yunjian/paint/库", Path(__file__).resolve().parents[2] / "库"]:
        if (p / "平台规格.md").exists():
            return p
    return None


def pending_platforms(lib):
    """平台规格.md 里标题下第一段写着「待核」的平台（整家没核的），出图前要停下。"""
    if not lib:
        return set()
    text = (lib / "平台规格.md").read_text(encoding="utf-8")
    out = set()
    for m in re.finditer(r"^### (\S+)[^\n]*\n+([^\n]*)", text, re.M):
        if m.group(2).startswith("**待核**"):
            out.add(m.group(1))
    return out


def check_items(items, lib, owner_only=False, confirmed=True):
    errs, pend = [], pending_platforms(lib)
    for i, it in enumerate(items, 1):
        if not isinstance(it, dict):
            errs.append(f"要什么第 {i} 项要写成 {{\"图类\", \"张数\", \"平台\", \"来源\"}}")
            continue
        if it.get("图类") not in MENU:
            errs.append(f"要什么第 {i} 项图类「{it.get('图类')}」不在菜单里（菜单外的写「菜单外」）")
        if not isinstance(it.get("张数"), int) or it.get("张数", 0) < 1:
            errs.append(f"要什么第 {i} 项张数要是 ≥1 的整数")
        if it.get("来源") not in SOURCE:
            errs.append(f"要什么第 {i} 项来源只能是「主人」或「推荐」")
        if owner_only and it.get("来源") != "主人":
            errs.append(f"要什么第 {i} 项是推荐加的——单图只出主人说到的图")
        elif it.get("来源") == "推荐" and not confirmed:
            errs.append(f"要什么第 {i} 项是推荐加的，主人还没点头——没点头的图类不出")
        if isinstance(it.get("平台"), str) and it["平台"] in pend:
            errs.append(f"要什么第 {i} 项平台「{it['平台']}」规格还没核对官方，先停下核，不出成品")
    return errs


def check_single(data, lib=None):
    errs = [f"缺「{k}」" for k in KEYS_SINGLE if k not in data]
    if errs:
        return errs
    if data.get("锁"):
        errs.append("单图不锁人、不锁货；要锁同一个人或同一件货就是系列图（判档卡），改走七问需求单")
    if data.get("套餐"):
        errs.append("单图没有套餐；主人要整套就是系列图")
    if not isinstance(data["平台"], list):
        errs.append("平台要写成列表（不发平台的写 [\"通用\"]）")
    items = data["要什么"] if isinstance(data["要什么"], list) and data["要什么"] else []
    if not items:
        errs.append("要什么至少一项（只写主人说到的图）")
    errs += check_items(items, lib, owner_only=True)
    idea = data["想法"]
    if not isinstance(idea, str) or not idea.strip():
        errs.append("想法要写成一段话：主体、画面、风格（聊天里那三四行）")
    elif len(idea.strip().splitlines()) > 4:
        errs.append("想法写长了：三四行以内，细节放进提示词")
    n = sum(it.get("张数", 0) for it in items if isinstance(it, dict) and isinstance(it.get("张数"), int))
    ps = data["提示词"]
    if not isinstance(ps, list) or not all(isinstance(x, str) and x.strip() for x in ps):
        errs.append("提示词要写成列表，一张一段")
    elif n and len(ps) not in (1, n):
        errs.append(f"提示词 {len(ps)} 段，张数 {n}：一张一段，或几张同一段")
    if not isinstance(data["提醒"], list):
        errs.append("提醒要写成列表（没有就写 []）")
    return errs


def check_brief(data, lib=None):
    if data.get("档") == "单图":
        return check_single(data, lib)
    if "档" in data and data["档"] not in DANG:
        return [f"档只能是 {DANG}"]
    errs = []
    for k in KEYS:
        if k not in data:
            errs.append(f"缺「{k}」")
    if errs:
        return errs
    if data["主体"] not in ZHUTI:
        errs.append(f"主体「{data['主体']}」不在 {ZHUTI} 里")
    if not isinstance(data["平台"], list) or not data["平台"]:
        errs.append("平台要写成至少一项的列表")
    items = data["要什么"]
    if not isinstance(items, list) or not items:
        errs.append("要什么至少一项（只写主人说到的图）")
        items = []
    errs += check_items(items, lib, confirmed=data["主人确认"])
    if not isinstance(data["套餐"], bool):
        errs.append("套餐只能是 true / false（主人明说整套才是 true）")
    for k in ["景", "参考"]:
        v = data[k]
        if not isinstance(v, dict) or "选" not in v or v.get("来源") not in SOURCE:
            errs.append(f"{k}要写成 {{\"选\": …, \"来源\": \"主人\"/\"推荐\"}}")
    b = data["品牌元素"]
    if not isinstance(b, dict) or b.get("加不加") not in BRAND:
        errs.append(f"品牌元素「加不加」只能是 {BRAND}")
    if not isinstance(data["主人确认"], bool):
        errs.append("主人确认只能是 true / false")
    if not isinstance(data["提醒"], list):
        errs.append("提醒要写成列表（没有就写 []）")
    if data.get("档") == "系列图" and (not isinstance(data.get("锁"), list) or not data["锁"]):
        errs.append("系列图要写「锁」：这单锁住的人、货（如 [\"商品：米白开衫\"]）；锁不出东西就是单图（判档卡）")
    return errs


def parse_card(text):
    if not text.startswith("---\n"):
        return None, text
    end = text.find("\n---\n", 4)
    if end < 0:
        return None, text
    head = {}
    for line in text[4:end].splitlines():
        if ":" in line:
            k, v = line.split(":", 1)
            head[k.strip()] = v.strip()
    return head, text[end + 5:]


def check_card(path):
    """只查一张卡：卡头、类、id 和文件名、正文小节。"""
    head, body = parse_card(Path(path).read_text(encoding="utf-8"))
    if head is None:
        return ["没有卡头（开头 --- 之间）"]
    kinds = {kind: (need, secs) for kind, need, secs in CARD_KINDS.values()}
    if head.get("类") not in kinds:
        return [f"类「{head.get('类')}」不认识，只能是 {list(kinds)}"]
    need, secs = kinds[head["类"]]
    errs = [f"卡头缺「{k}」" for k in COMMON + need if not head.get(k)]
    if head.get("id") != Path(path).stem:
        errs.append(f"id「{head.get('id')}」和文件名不一致")
    errs += [f"少了「## {s}」一节" for s in secs if f"## {s}\n" not in body]
    return errs


def check_library(lib):
    errs, ids = [], {}
    for sub, (kind, need, sections) in CARD_KINDS.items():
        d = lib / sub
        cards = sorted(d.glob("*.md")) if d.is_dir() else []
        cards = [c for c in cards if c.name != "README.md" and not c.name.startswith("好图标准")]
        if len(cards) < 2:
            errs.append(f"{sub}/ 只有 {len(cards)} 张卡，每类至少能挑 2～3 个")
        readme = (d / "README.md").read_text(encoding="utf-8") if (d / "README.md").exists() else ""
        if not readme:
            errs.append(f"{sub}/ 缺 README.md 目录")
        for c in cards:
            head, body = parse_card(c.read_text(encoding="utf-8"))
            rel = f"{sub}/{c.name}"
            if head is None:
                errs.append(f"{rel}: 没有卡头（开头 --- 之间）")
                continue
            for k in COMMON + need:
                if not head.get(k):
                    errs.append(f"{rel}: 卡头缺「{k}」")
            if head.get("类") != kind:
                errs.append(f"{rel}: 类应是「{kind}」，写的是「{head.get('类')}」")
            if head.get("id") != c.stem:
                errs.append(f"{rel}: id「{head.get('id')}」和文件名不一致")
            if head.get("id") in ids:
                errs.append(f"{rel}: id 和 {ids[head['id']]} 重复")
            ids[head.get("id")] = rel
            for s in sections:
                if f"## {s}\n" not in body:
                    errs.append(f"{rel}: 少了「## {s}」一节")
            if readme and head.get("id") not in readme:
                errs.append(f"{rel}: README.md 目录里没列这张")
    for sub in CARD_KINDS:
        readme = lib / sub / "README.md"
        if readme.exists():
            for cid in re.findall(r"\b((?:scene|brand|ref)-[a-z0-9-]+)\b", readme.read_text(encoding="utf-8")):
                if cid not in ids:
                    errs.append(f"{sub}/README.md 列了 {cid}，库里没有这张卡")
    if not (lib / "参考" / "好图标准.md").exists():
        errs.append("参考/ 缺 好图标准.md")
    return errs


def main(argv):
    if not argv or argv[0] in ("-h", "--help"):
        print(__doc__)
        return 0
    if argv[0] == "--card":
        errs = check_card(argv[1]) if len(argv) > 1 else ["要写卡的路径"]
        for e in errs:
            print("❌", e)
        print("✅ 通过" if not errs else f"共 {len(errs)} 处问题")
        return 1 if errs else 0
    if argv[0] == "--library":
        lib = find_lib(argv[1] if len(argv) > 1 else None)
        if not lib:
            print("❌ 找不到库（要有 平台规格.md）")
            return 1
        errs = check_library(lib)
    else:
        lib_arg = argv[argv.index("--lib") + 1] if "--lib" in argv else None
        lib = find_lib(lib_arg)
        try:
            data = json.loads(Path(argv[0]).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as e:
            print(f"❌ 读不了需求单：{e}")
            return 1
        errs = check_brief(data, lib)
        if not lib:
            print("⚠️ 没找到库，没查平台是不是还没核规格")
    for e in errs:
        print("❌", e)
    print("✅ 通过" if not errs else f"共 {len(errs)} 处问题")
    return 1 if errs else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

files.check_paint.py:
"""丹青机械自检：一单的成品对平台规格、对需求单（只用标准库读尺寸；查白底四角要 Pillow 或 sips，没有就提醒）。
用法：python3 check_paint.py <作品文件夹> [--brief 需求单.json] [--table 规格表.json]
作品文件夹里要有 交付清单.json：[{"文件": "成品-1.jpg", "第几张": 1, "平台": "抖店", "图类": "1:1 主图"}, …]
  同一张图的几个版本（抖音竖、横两版封面；公众号 2.35:1 和 1:1 两裁）写同一个「第几张」，和需求单比张数时只算一张。
查：文件在不在；像素（主人另给了「像素」就必须一样；和丹青默认交付像素不同只提醒，官方规格才是硬的）；比例；不低于官方下限、不超过上限；文件大小；白底四角；
    和需求单比张数——少了、多了（出了单子上没有的图）都算错；规格表里没有的平台和图类（待核）要停下。
有问题打印 ❌ 并以 1 退出；只有提醒（⚠️）照样算过。"""
import argparse
import json
import re
import sys
from collections import Counter
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE.parent / "paint-adjust"))
from 调图页 import png_size  # noqa: E402  只用标准库读 PNG、JPEG 尺寸


ALIAS = {"视频封面": "封面"}  # 交付清单里分得更细的图类，对回需求单菜单里的名字
EXTREME = ["最", "第一", "顶级", "极致", "绝对", "100%", "国家级", "唯一", "首选"]
CONTACT = re.compile(r"1[3-9]\d{9}|微信|VX|vx|加V|wx[:：]|二维码|私信领")


def find_table(arg=None):
    for p in ([Path(arg).expanduser()] if arg else []) + [Path.home() / ".yunjian/paint/库/规格表.json", HERE.parents[1] / "库" / "规格表.json"]:
        if p.exists():
            return json.loads(p.read_text(encoding="utf-8"))
    return None


def ratio_of(text):
    a, b = (float(x) for x in text.split(":"))
    return a / b


def check_one(path, spec, want=None):
    """一张图对一条规格。want＝主人另给的像素 [宽, 高]（优先于交付像素）。"""
    errs, warns = [], []
    try:
        w, h = png_size(path)
    except (SystemExit, OSError, IndexError):
        return [f"{path.name}: 读不出尺寸（不是 png/jpg，或文件坏了）"], warns
    if want:  # 主人明确要的像素：对不上就是错
        if want[0] and w != want[0]:
            errs.append(f"{path.name}: 宽 {w}，主人要 {want[0]}")
        if want[1] and h != want[1]:
            errs.append(f"{path.name}: 高 {h}，主人要 {want[1]}")
    else:  # 丹青默认的交付像素是自己定的，不卡人：官方规格满足就只提醒
        d = spec.get("交付") or [None, None]
        if (d[0] and w != d[0]) or (d[1] and h != d[1]):
            warns.append(f"{path.name}: {w}x{h} 不是丹青默认的 {d[0]}x{d[1] or '?'}；官方规格查下来能传")
    r = w / h
    if "比例" in spec and abs(r - ratio_of(spec["比例"])) > 0.01 * ratio_of(spec["比例"]):
        errs.append(f"{path.name}: 比例 {w}:{h} 不是 {spec['比例']}")
    if "比例范围" in spec:
        lo, hi = spec["比例范围"]
        if not lo - 0.005 <= r <= hi + 0.005:
            errs.append(f"{path.name}: 比例 {r:.3f} 不在官方范围 {lo}～{hi}（宽/高）")
    if "最小" in spec:
        mw, mh = spec["最小"]
        short, long_ = (min(w, h), max(w, h)) if "比例范围" in spec else (w, h)
        if short < mw or long_ < mh:
            errs.append(f"{path.name}: {w}x{h} 低于官方下限 {mw}x{mh}")
    if "最大" in spec and (w > spec["最大"][0] or h > spec["最大"][1]):
        errs.append(f"{path.name}: {w}x{h} 超过官方上限 {spec['最大'][0]}x{spec['最大'][1]}")
    if "宽范围" in spec and not spec["宽范围"][0] <= w <= spec["宽范围"][1]:
        errs.append(f"{path.name}: 宽 {w} 不在 {spec['宽范围'][0]}～{spec['宽范围'][1]}")
    if "高上限" in spec and h > spec["高上限"]:
        errs.append(f"{path.name}: 高 {h} 超过 {spec['高上限']}")
    mb = path.stat().st_size / 1024 / 1024
    if spec.get("上限MB") and mb > spec["上限MB"]:
        errs.append(f"{path.name}: {mb:.2f}MB 超过 {spec['上限MB']}MB")
    if spec.get("白底"):
        try:
            sys.path.insert(0, str(HERE.parent / "paint-make"))
            from 交付 import corners
            bad = [c for c in corners(path) if tuple(c[:3]) != (255, 255, 255)]
            if bad:
                errs.append(f"{path.name}: 白底四角不是纯白 {tuple(bad[0][:3])}")
        except Exception:  # 没有 Pillow 也没有 sips
            warns.append(f"{path.name}: 这里查不了白底四角，交付前请用看图核一眼背景是不是纯白")
    if spec.get("官方未定"):
        warns.append(f"{path.name}: 这种图官方没定统一尺寸，像素是丹青默认的，交付时说一句")
    return errs, warns


def check_folder(folder, table, brief=None):
    folder = Path(folder)
    errs, warns = [], []
    lst = folder / "交付清单.json"
    if not lst.exists():
        return [f"{folder.name}: 没有 交付清单.json"], warns
    items = json.loads(lst.read_text(encoding="utf-8"))
    for it in items:
        key = f"{it.get('平台')}|{it.get('图类')}"
        spec = table.get(key)
        f = folder / str(it.get("文件"))
        if spec is None:
            errs.append(f"{it.get('文件')}: 「{key}」规格表里没有（平台待核或图类写错）——先核规格，不交付")
            continue
        if not f.exists():
            errs.append(f"{it.get('文件')}: 文件不在")
            continue
        e, w = check_one(f, spec, it.get("像素"))
        errs += e
        warns += w
    for lay in sorted(folder.glob("图层*.json")):  # 图层上的字：极限词、联系方式只提醒，主人定
        try:
            texts = [L.get("text", "") for L in json.loads(lay.read_text(encoding="utf-8")) if L.get("type") == "text"]
        except (ValueError, AttributeError):
            warns.append(f"{lay.name}: 读不了")
            continue
        for t in texts:
            hit = [w for w in EXTREME if w in t]
            if hit:
                warns.append(f"{lay.name}: 「{t}」里有「{'、'.join(hit)}」——广告法极限词风险，提醒主人")
            if CONTACT.search(t):
                warns.append(f"{lay.name}: 「{t}」像联系方式——小红书、抖音等禁导流，提醒主人")
    if brief:
        want = Counter()
        for x in brief.get("要什么", []):
            if isinstance(x, dict) and isinstance(x.get("张数"), int):
                want[(x.get("平台"), x.get("图类"))] += x["张数"]
        seen = {}
        for i, it in enumerate(items):
            base = str(it.get("图类", "")).split("·")[0]
            seen.setdefault((it.get("平台"), ALIAS.get(base, base)), set()).add(it.get("第几张", f"文件{i}"))
        got = Counter({k: len(v) for k, v in seen.items()})
        for k, n in want.items():
            if got.get(k, 0) < n:
                errs.append(f"需求单要 {k[0]} {k[1]} {n} 张，只出了 {got.get(k, 0)} 张")
        for k, n in got.items():
            if k not in want and not brief.get("套餐"):
                errs.append(f"出了需求单上没有的图：{k[0]} {k[1]} {n} 张——没要的不出")
            elif k in want and n > want[k] and not brief.get("套餐"):
                errs.append(f"{k[0]} {k[1]} 出了 {n} 张，需求单只要 {want[k]} 张")
    return errs, warns


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("folder")
    ap.add_argument("--brief")
    ap.add_argument("--table")
    a = ap.parse_args(argv)
    table = find_table(a.table)
    if table is None:
        print("❌ 找不到 规格表.json")
        return 1
    brief = json.loads(Path(a.brief).read_text(encoding="utf-8")) if a.brief else None
    errs, warns = check_folder(a.folder, table, brief)
    for e in errs:
        print("❌", e)
    for w in warns:
        print("⚠️", w)
    print("✅ 机械自检通过" if not errs else f"共 {len(errs)} 处不合格")
    return 1 if errs else 0


if __name__ == "__main__":
    sys.exit(main())

